window.HB_TR["romans"]["ur"]=["1۔ پولس، یسوع مسیح کا بندہ، رسول بننے کے لیے بلایا گیا، خدا کی انجیل سے جدا ہو گیا،\n2۔ (جس کا وعدہ اس نے پہلے اپنے نبیوں نے مقدس صحیفوں میں کیا تھا،)\n3۔ اپنے بیٹے یسوع مسیح ہمارے رب کے بارے میں، جو جسم کے مطابق داؤد کی نسل سے بنا تھا؛\n4. اور خدا کا بیٹا قرار دیا گیا، جو طاقت کے ساتھ، روح پاکیزگی کے مطابق، مردوں سے زندہ ہونے کے ذریعے: {اعلان شدہ: Gr. detriined}\n5۔ جس کے ذریعے ہمیں فضل اور رسولی ملی ہے، تمام قوموں میں ایمان کی اطاعت کے لیے، اس کے نام کے لیے: {اطاعت کے لیے...: یا، ایمان کی اطاعت کے لیے}\n6۔ جن میں سے آپ یسوع مسیح کے بلائے ہوئے بھی ہیں:\n7۔ روم میں موجود تمام لوگوں کے لیے، جو خدا کے محبوب ہیں، جنہیں مقدس بننے کے لیے بلایا گیا ہے: آپ پر فضل اور ہمارے باپ اور خداوند یسوع مسیح کی طرف سے امن ہو۔\n8. سب سے پہلے، میں اپنے خدا کا یسوع مسیح کے ذریعے آپ سب کے لیے شکر ادا کرتا ہوں کہ آپ کا ایمان پوری دنیا میں بیان کیا جاتا ہے۔\n9۔ خدا میرا گواہ ہے، جس کی میں اپنی روح سے اس کے بیٹے کی خوشخبری میں خدمت کرتا ہوں، کہ میں ہمیشہ اپنی دعاؤں میں تمہارا ذکر کرتا ہوں؛ {ساتھ: یا، ان}\n10۔ درخواست کرنا، اگر کسی بھی طرح اب میں خدا کی مرضی سے آپ کے پاس آنے کے لیے خوشحال سفر کر سکوں۔\n11. کیونکہ میں تمہیں دیکھنے کی خواہش رکھتا ہوں، تاکہ میں تمہیں کوئی روحانی تحفہ دے سکوں، تاکہ تم قائم ہو جاؤ؛\n12. یعنی، تاکہ میں آپ دونوں کے باہمی ایمان سے آپ کے ساتھ تسلی پا سکوں۔ {ساتھ: یا، ان}\n13. اب میں نہیں چاہتا کہ تم جاہل ہو جاؤ، بھائیو، کہ اکثر میں تم سے آنے کا ارادہ رکھتا تھا، (لیکن اب تک اجازت دی گئی تھی)، تاکہ تم میں بھی کچھ پھل مل سکے، جیسے دوسرے غیر یہودیوں میں۔ {درمیان: OR, IN}\n14. میں یونانیوں اور وحشیوں دونوں کا مقروض ہوں؛ دونوں، دانا اور نادانوں کے لیے۔\n15۔ تو، جتنا میں ہوں، میں تم لوگوں کو جو روم میں ہیں بھی خوشخبری سنانے کے لیے تیار ہوں۔\n16۔ کیونکہ میں مسیح کی خوشخبری سے شرمندہ نہیں ہوں: کیونکہ یہ خدا کی طاقت ہے کہ وہ ہر ایمان والے کو نجات دے؛ پہلے یہودی کو، اور یونانی کے لیے بھی۔\n17۔ کیونکہ اسی میں خدا کی راستبازی ایمان سے ایمان تک ظاہر ہوتی ہے: جیسا کہ لکھا ہے، نیک لوگ ایمان سے زندہ رہیں گے۔\n18۔ کیونکہ خدا کا غضب آسمان سے ان تمام بے دینی اور بدکاری کے خلاف ظاہر ہوتا ہے جو بدکاری میں سچائی رکھتے ہیں؛\n19۔ کیونکہ جو کچھ خدا کے بارے میں معلوم ہو سکتا ہے وہ ان میں ظاہر ہے؛ کیونکہ خدا نے انہیں یہ دکھایا ہے۔ {ان میں: یا، ان کے لیے}\n20۔ کیونکہ دنیا کی تخلیق سے اس کی غیر مرئی چیزیں واضح طور پر دیکھی جاتی ہیں، جو ان چیزوں سے سمجھی جاتی ہیں جو بنائی گئی ہیں، {حتیٰ کہ} اس کی ابدی طاقت اور خدای؛ تاکہ وہ بغیر کسی عذر کے ہوں: {تو...: یا، کہ وہ ہو سکتے ہیں}\n21. کیونکہ جب انہوں نے خدا کو جانا، تو انہوں نے {اسے} کو خدا کے طور پر نہیں بلکہ شکر گزار کیا؛ لیکن ان کے خیالات میں خود پسند ہو گئے، اور ان کا بے وقوف دل تاریک ہو گیا۔\n22۔ خود کو دانا سمجھ کر، وہ بے وقوف بن گئے،\n23۔ اور ناقابل فہم خدا کی شان کو ایک ایسی تصویر میں بدل دیا جو بگڑنے والے انسان، پرندوں، چار پاؤں والے جانوروں اور رینگنے والے جانوروں کی طرح بن گئی۔\n24۔ اسی لیے خدا نے انہیں اپنے دلوں کی خواہشات کے ذریعے ناپاکی کے حوالے کر دیا، تاکہ وہ اپنے جسموں کو آپس میں بے عزتی کریں:\n25۔ جس نے خدا کی سچائی کو جھوٹ میں بدل دیا، اور مخلوق کی عبادت اور خدمت اس سے زیادہ کی جو ہمیشہ کے لیے بابرکت ہے۔ آمین۔ {مزید: یا یوں کہیے}\n26۔ اسی وجہ سے خدا نے انہیں نفرت انگیز محبت کے حوالے کر دیا: کیونکہ ان کی عورتوں نے بھی قدرتی استعمال کو فطرت کے خلاف استعمال میں بدل دیا:\n27۔ اسی طرح مرد بھی، عورت کے قدرتی استعمال کو چھوڑ کر، ایک دوسرے کی ہوس میں جل گئے؛ ایسے مرد جن کے لوگ نامناسب کام کر رہے تھے، اور اپنے اندر اپنی غلطی کا وہ کفارہ وصول کر رہے تھے جو پورا ہوا۔\n28۔ اور اگرچہ وہ خدا کو اپنے علم میں برقرار رکھنا نہیں چاہتے تھے، خدا نے انہیں ایک ملامت شدہ ذہن کے سپرد کر دیا، تاکہ وہ کام کریں جو آسان نہیں ہیں؛ {برقرار رکھنے کے لیے: یا، تسلیم کرنے کے لیے} {ایک بدتمیز...: یا، ایک ایسا ذہن جو فیصلہ سے خالی ہو یا، ایک ناپسندیدہ ذہن}\n29۔ تمام ناانصافی،، بدکاری، لالچ، بد نیت سے بھرے ہونا؛ حسد، قتل، بحث، دھوکہ دہی، بد نیتی سے بھرپور؛ سرگوشیاں،\n30۔ غیبت کرنے والے، خدا سے نفرت کرنے والے، نفرت کرنے والے، مغرور، شیخی مارنے والے، برے کاموں کے موجد، والدین کی نافرمان،\n31. بغیر سمجھ کے، عہد توڑنے والے، بغیر قدرتی محبت کے، بے رحم، بے رحم: {بغیر فطری...: یا غیر ملنسار کے}\n32۔ جو خدا کے فیصلے کو جانتے ہیں کہ جو ایسے کام کرتے ہیں وہ موت کے لائق ہیں، نہ صرف ایسا ہی کرتے ہیں بلکہ ان سے خوشی حاصل کرتے ہیں جو یہ کام کرتے ہیں۔ {have...: یا، رضامندی کے ساتھ}","1. اس لیے تم ناقابل معافی ہو، اے انسان، جو بھی تم فیصلہ کرنے والا ہو: جہاں تم کسی اور کا فیصلہ کرتے ہو، تم خود کو سزا دیتے ہو؛ کیونکہ تم جو فیصلہ کرتا ہے وہی کرتا ہے۔\n2۔ لیکن ہم یقین رکھتے ہیں کہ خدا کا فیصلہ ان لوگوں کے خلاف سچائی کے مطابق ہے جو ایسا کرتے ہیں۔\n3۔ اور کیا تم یہ سمجھتے ہو، اے انسان، جو ان لوگوں کا فیصلہ کرتا ہے جو ایسا کرتے ہیں اور کرتے ہیں، کہ تم خدا کے فیصلے سے بچ جاؤ گے؟\n4۔ یا تم اس کی نیکی، برداشت اور صبر کی دولت سے نفرت کرتے ہو؟ یہ نہ جانتے ہوئے کہ خدا کی بھلائی تمہیں توبہ کی طرف لے جاتی ہے؟\n5. لیکن جب تمہاری سختی اور بے باک دل اپنے لیے غضب کے دن اور خدا کے راستباز فیصلے کے انکشاف کے خلاف اپنے لیے محفوظ کر لیتا ہے؛\n6۔ جو ہر انسان کو اس کے اعمال کے مطابق پیش کرے گا:\n7۔ ان لوگوں کے لیے جو صبر سے نیکی میں ثابت قدمی سے عظمت، عزت اور ابدی زندگی کی تلاش میں ہیں:\n8۔ لیکن جو جھگڑالو ہیں اور سچائی کی اطاعت نہیں کرتے، بلکہ ناانصافی، غصہ اور غضب کی اطاعت کرتے ہیں،\n9۔ ہر انسان کی جان پر جو برائی کرتا ہے، سب سے پہلے یہودی اور غیر یہودی پر بھی، مصیبت اور اذیت؛ {غیر یہودی: یونانی زبان میں}\n10۔ بلکہ جلال، عزت اور امن، ہر اس انسان کے لیے جو نیکی کرتا ہے، پہلے یہودی کے لیے، اور غیر یہودی کے لیے بھی: {غیر یہودی: یونانی یونانی}\n11۔ کیونکہ خدا کے ساتھ لوگوں کی کوئی عزت نہیں ہوتی۔\n12۔ کیونکہ جو لوگ قانون کے بغیر گناہ کریں گے، وہ قانون کے بغیر بھی ہلاک ہوں گے؛ اور جتنے بھی قانون میں گناہ کریں گے، ان کا فیصلہ قانون کے مطابق ہوگا؛\n13۔ (کیونکہ شریعت کے سننے والے خدا کے سامنے درست نہیں بلکہ شریعت کے عمل کرنے والے انصاف کے مستحق ہوں گے۔\n14۔ کیونکہ جب غیر یہودی، جن کے پاس قانون نہیں، فطرتا شریعت میں شامل چیزیں کرتے ہیں، تو وہ جو قانون نہیں رکھتے، خود ایک قانون ہوتے ہیں:\n15۔ جو ان کے دلوں میں لکھا قانون کے کام کو ظاہر کرتا ہے، ان کا ضمیر بھی گواہی دیتا ہے، اور ان کے خیالات بھی ایک دوسرے پر الزام لگاتے یا معافی دیتے ہیں؛) {ان کا ضمیر...: یا، وہ ضمیر جو ان کے ساتھ گواہ ہے} {درمیان...: یا، اپنے درمیان}\n16۔ اس دن جب خدا یسوع مسیح کے ذریعے میرے انجیل کے مطابق انسانوں کے رازوں کا فیصلہ کرے گا۔\n17۔ دیکھو، تم یہودی کہلائے گئے ہو، اور شریعت میں پابند ہو، اور خدا پر فخر کرو،\n18۔ اور اپنی مرضی کو جانتا ہے، اور شریعت سے تعلیم یافتہ چیزوں کی منظوری دیتا ہے؛ {منظور...: یا، ان چیزوں کو آزمائیں جو مختلف ہیں}\n19۔ اور یقین رکھو کہ تم خود اندھوں کا رہنما ہو، ان کی روشنی جو اندھیرے میں ہیں،\n20۔ بے وقوفوں کا استاد، بچوں کا استاد، جس کے پاس علم اور قانون کی سچائی کی صورت ہو۔\n21. تو تم جو دوسروں کو سکھاتے ہو، خود کو نہیں سکھاتے؟ تم جو کسی کو چوری نہ کرنے کی نصیحت کرتے ہو، کیا تم چوری کرتے ہو؟\n22۔ جو کہتی ہے کہ انسان نہیں کرے، کیا تم کرتی ہو؟ تم جو بتوں سے نفرت کرتے ہو، کیا تم بے حرمتی کرتے ہو؟\n23. تو جو قانون پر فخر کرتے ہو، قانون توڑ کر خدا کی بے عزتی کرتے ہو؟\n24. کیونکہ خدا کا نام غیر یہودیوں میں تمہارے ذریعے کفر کیا جاتا ہے، جیسا کہ لکھا ہے۔\n25۔ کیونکہ ختنہ واقعی فائدہ مند ہے، اگر تم قانون کی پابندی کرو، لیکن اگر تم قانون توڑو تو تمہارا ختنہ غیر ختنہ ہے۔\n26۔ لہٰذا اگر غیر ختنہ کرنے والا شریعت کی راستبازی کو پورا کرتا ہے، تو کیا اس کا غیر ختنہ ختنہ شمار نہیں ہوگا؟\n27۔ اور کیا ختنہ نہ کرنا، جو فطرتا ہے، اگر وہ قانون کو پورا کرتا ہے، تمہیں فیصلہ نہیں کرے گا، جو حرف اور ختنہ کے ذریعے قانون کی خلاف ورزی کرتا ہے؟\n28۔ کیونکہ وہ ظاہری طور پر یہودی نہیں ہے؛ نہ ہی {یہ} ختنہ ہے، جو جسم میں باہر کی طرف ہے:\n29۔ لیکن وہ ایک یہودی ہے، جو کہ اندرونی طور پر یہودی ہے؛ اور ختنہ {کیا ہے} دل کی، روح میں، {اور} حرف میں نہیں؛ جس کی حمد انسانوں کی نہیں، بلکہ خدا کی ہے۔","1. پھر یہودی کو کیا فائدہ حاصل ہے؟ یا ختنہ کا کیا فائدہ ہے؟\n2۔ ہر لحاظ سے: خاص طور پر، کیونکہ خدا کے پیش گوئیاں ان کے سپرد تھیں۔\n3۔ اگر کچھ لوگ ایمان نہ لائیں؟ کیا ان کا کفر خدا کے ایمان کو بے اثر کر دے گا؟\n4۔ خدا نہ کرے: ہاں، خدا سچا ہو، لیکن ہر انسان جھوٹا ہے؛ جیسا کہ لکھا ہے، تاکہ تم اپنی باتوں میں درست ثابت ہو، اور جب تمہارا فیصلہ ہو تو تم غالب آ سکو۔\n5. لیکن اگر ہماری ناراستی خدا کی راستبازی کی تعریف کرے، تو ہم کیا کہیں؟ {ہے} خدا بدکار ہے جو انتقام لیتا ہے؟ (میں مرد کی حیثیت سے بات کرتا ہوں)\n6. خدا نہ کرے: تو پھر خدا دنیا کا فیصلہ کیسے کرے گا؟\n7۔ کیونکہ اگر خدا کی سچائی میرے جھوٹ کے ذریعے اس کی جلال سے زیادہ پھیلی ہو؛ پھر بھی مجھے گناہ گار کیوں سمجھا جاتا ہے؟\n8. اور نہ کہ {بلکہ}، (جیسا کہ ہمیں بدنامی سے رپورٹ کیا جاتا ہے، اور کچھ لوگ اس بات کی تصدیق کرتے ہیں کہ ہم کہتے ہیں،) آؤ ہم برائی کریں، تاکہ بھلائی آ جائے؟ جس کی لعنت منصفانہ ہے۔\n9. پھر کیا؟ کیا ہم ان سے بہتر ہیں؟ نہیں، بالکل نہیں: کیونکہ ہم نے پہلے بھی یہودیوں اور غیر یہودیوں دونوں کو ثابت کر دیا ہے کہ وہ سب گناہ کے تحت ہیں؛ {ثابت شدہ: Gr. charged}\n10۔ جیسا کہ لکھا ہے، کوئی راستباز نہیں، نہیں، کوئی نہیں:\n11۔ کوئی نہیں جو سمجھتا ہو، کوئی نہیں جو خدا کی تلاش کرتا ہو۔\n12. وہ سب راستے سے ہٹ چکے ہیں، وہ مل کر غیر منافع بخش ہو جاتے ہیں؛ کوئی بھی اچھا کام نہیں کرتا، نہیں، کوئی بھی نہیں۔\n13۔ ان کا گلا کھلا قبر ہے؛ انہوں نے اپنی زبانوں سے دھوکہ دیا ہے؛ ایسپس کا زہر {ہے} ان کے ہونٹوں کے نیچے:\n14۔ جس کا منہ لعنتوں اور تلخی سے بھرا ہوا ہے:\n15. ان کے پاؤں خون بہانے کے لیے تیز ہیں:\n16۔ تباہی اور مصیبت اپنے طریقوں میں ہیں:\n17۔ اور امن کے راستے کو انہوں نے نہیں جانا:\n18۔ ان کی آنکھوں کے سامنے خدا کا خوف نہیں ہوتا۔\n19۔ اب ہم جانتے ہیں کہ جو کچھ بھی شریعت کہتا ہے، وہ ان لوگوں سے کہتا ہے جو شریعت کے تحت ہیں: کہ ہر زبان بند ہو جائے اور پوری دنیا خدا کے سامنے قصوروار ہو جائے۔ {قصوروار...: یا، خدا کے فیصلے کے تابع}\n20. لہٰذا قانون کے اعمال سے اس کی نظر میں کوئی جسم جائز نہیں ہوگا، کیونکہ شریعت کے مطابق گناہ کا علم ہے۔\n21. لیکن اب خدا کی راستبازی قانون کے بغیر ظاہر ہوتی ہے، جو شریعت اور انبیاء کے ذریعے گواہی دی جاتی ہے؛\n22۔ یہاں تک کہ خدا کی راستبازی {جو یسوع مسیح کے ایمان کے ذریعے سب کے لیے اور ان سب پر ہے جو ایمان لاتے ہیں: کیونکہ کوئی فرق نہیں:\n23۔ کیونکہ سب نے گناہ کیا ہے، اور خدا کی شان سے محروم ہو گئے ہیں؛\n24۔ مسیح یسوع میں موجود نجات کے ذریعے اس کے فضل سے آزادانہ طور پر راستبازی حاصل کرنا:\n25۔ جسے خدا نے اپنے خون پر ایمان کے ذریعے کفارہ بنانے کے لیے مقرر کیا ہے، تاکہ وہ ماضی کے گناہوں کی معافی کے لیے اپنی راستبازی کا اعلان کرے، خدا کی برداشت کے ذریعے؛ {بیان کریں: یا، پہلے سے مقدر ہے} {ریمیشن: یا، گزرنا}\n26. اس وقت اپنی راستبازی کا اعلان کرنا، {میں کہتا ہوں}: تاکہ وہ عادل ہو سکے، اور یسوع پر ایمان لانے والے کا راستبین ہو۔\n27۔ پھر کہاں فخر کر رہے ہیں؟ اسے خارج کر دیا گیا ہے۔ کس قانون کے تحت؟ کاموں سے؟ نہیں: بلکہ ایمان کے قانون کے مطابق۔\n28۔ لہٰذا ہم نتیجہ اخذ کرتے ہیں کہ انسان ایمان کے ذریعے انصاف پاتا ہے بغیر قانون کے اعمال کے۔\n29. کیا وہ صرف یہودیوں کا خدا ہے؟ {کیا وہ} بھی غیر یہودیوں کا نہیں ہے؟ جی ہاں، غیر یہودیوں کے بارے میں بھی:\n30۔ دیکھنا {یہ} ایک خدا ہے، جو ختنہ کو ایمان کے ذریعے اور غیر ختنہ کو ایمان کے ذریعے جائز بنائے گا۔\n31۔ کیا پھر ہم ایمان کے ذریعے قانون کو کالعدم بنا دیتے ہیں؟ خدا نہ کرے: ہاں، ہم قانون قائم کرتے ہیں۔","1. تو پھر ہم کیا کہیں کہ ہمارے باپ ابراہیم نے جسمانی طور پر کیا پایا ہے؟\n2۔ اگر ابراہیم کو اعمال سے راستباز بنایا گیا تو اسے جلال حاصل ہے؛ لیکن خدا کے سامنے نہیں۔\n3۔ کیونکہ کتاب مقدس میں کیا کہا گیا ہے؟ ابراہیم نے خدا پر ایمان لایا، اور اسے راستبازی کے لیے شمار کیا گیا۔\n4. اب جو کام کرتا ہے اس کے لیے انعام فضل کا نہیں بلکہ قرض کا ہے۔\n5۔ لیکن جو کام نہیں کرتا بلکہ اس پر ایمان رکھتا ہے جو نادینوں کو راستباز بناتا ہے، اس کا ایمان راستبازی کے لیے شمار ہوتا ہے۔\n6۔ جیسے داؤد نے بھی اس انسان کی برکت بیان کی ہے، جس پر خدا بغیر اعمال راستبازی کا الزام دیتا ہے،\n7. {کہا}، مبارک ہیں وہ لوگ جن کے گناہوں کو معاف کیا گیا اور جن کے گناہ چھپے ہوئے ہیں۔\n8۔ مبارک وہ شخص ہے جس پر خداوند گناہ کا الزام نہیں لگاتا۔\n9۔ یہ برکت صرف ختنہ پر آتی ہے، یا ختنہ نہ کرنے پر بھی؟ کیونکہ ہم کہتے ہیں کہ ایمان ابراہیم کو راستبازی کے لیے گنتا تھا۔\n10. پھر اس کا حساب کیسے لگایا گیا؟ جب وہ ختنہ میں تھا، یا غیر ختنہ میں؟ ختنہ میں نہیں، بلکہ غیر ختنہ میں۔\n11۔ اور اسے ختنہ کی نشانی ملی، جو اس ایمان کی راستبازی کی مہر تھی جو {اس نے} ابھی تک ختنہ نہیں کی تھی: تاکہ وہ تمام ایمان والوں کا باپ بن سکے، چاہے وہ ختنہ شدہ نہ ہوں؛ تاکہ راستبازی ان پر بھی منسوب کی جا سکے:\n12۔ اور ختنہ کا باپ ان لوگوں کے لیے جو صرف ختنہ کے نہیں ہیں، بلکہ جو ہمارے باپ ابراہیم کے ایمان کے قدموں پر چلتے ہیں، جو {ابھی} غیر ختنہ شدہ تھا۔\n13۔ کیونکہ وعدہ کہ وہ دنیا کا وارث ہوگا، {تھا} ابراہیم یا اس کی نسل کو، قانون کے ذریعے نہیں، بلکہ ایمان کی راستبازی کے ذریعے۔\n14۔ کیونکہ اگر قانون کے لوگ وارث ہوں، تو ایمان باطل ہو جاتا ہے، اور وعدہ بے اثر ہو جاتا ہے:\n15۔ کیونکہ قانون غضب کا باعث بنتا ہے: جہاں کوئی قانون نہ ہو، وہاں کوئی خلاف ورزی نہیں ہوتی۔\n16. لہٰذا {یہ ایمان کا ہے} تاکہ {یہ فضل کے ذریعے ہو}؛ آخر تک وعدہ تمام بیج کے لیے یقینی ہو سکتا ہے؛ صرف شریعت کے لیے نہیں، بلکہ اس کے لیے بھی جو ابراہیم کے ایمان سے تعلق رکھتا ہے؛ جو ہم سب کا باپ ہے،\n17. (جیسا کہ لکھا ہے، میں نے تمہیں کئی قوموں کا باپ بنایا ہے،) اس کے سامنے جس پر اس نے ایمان لایا، {حتیٰ کہ} خدا بھی، جو مردوں کو زندہ کرتا ہے، اور ان چیزوں کو پکاتا ہے جو حقیقت میں نہیں ہوتیں۔ {اس کے سامنے: یا، اس کی طرح}\n18۔ جو امید کے خلاف امید پر ایمان رکھتا تھا، کہ وہ کئی قوموں کا باپ بن سکے، جیسا کہ کہا گیا، تیری نسل بھی ہوگی۔\n19۔ اور ایمان میں کمزور نہ ہونے کی وجہ سے، اس نے اپنے جسم کو مردہ نہیں سمجھا، جب وہ تقریبا سو سال کا تھا، اور نہ ہی سارہ کے رحم کی مردہ حالت کو:\n20۔ وہ خدا کے وعدے پر کفر کی وجہ سے نہیں لڑکھڑایا؛ لیکن ایمان میں مضبوط تھا، خدا کی جلال دیتا تھا؛\n21. اور مکمل طور پر قائل ہو کر کہ جو وعدہ کیا گیا تھا، وہ اسے بھی انجام دے سکتا ہے۔\n22۔ اسی لیے اسے راستبازی کے لیے منسوب کیا گیا۔\n23۔ یہ صرف اس کے لیے نہیں لکھا گیا تھا، بلکہ اسے اس پر منسوب کیا گیا تھا؛\n24۔ لیکن ہمارے لیے بھی، جن پر یہ الزام لگایا جائے گا، اگر ہم اس پر ایمان لائیں جس نے ہمارے خداوند یسوع کو مردوں میں سے زندہ کیا؛\n25۔ جو ہمارے جرائم کی سزا میں آزاد ہوا، اور ہمارے جواز کے لیے دوبارہ زندہ کیا گیا۔","1۔ اسی لیے ایمان کے ذریعے راستباز ہونے کی وجہ سے، ہم اپنے خداوند یسوع مسیح کے ذریعے خدا کے ساتھ امن رکھتے ہیں:\n2۔ جس کے ذریعے ہمیں ایمان کے ذریعے اس فضل تک رسائی حاصل ہے جس میں ہم کھڑے ہیں، اور خدا کی جلال کی امید میں خوشی مناتے ہیں۔\n3۔ اور نہ صرف {یوں}، بلکہ ہم مصیبتوں میں بھی فخر کرتے ہیں: جانتے ہیں کہ مصیبت صبر کا کام کرتی ہے؛\n4۔ اور صبر، تجربہ؛ اور تجربہ، امید:\n5۔ اور امید شرمندہ نہیں ہوتی؛ کیونکہ خدا کی محبت ہمارے دلوں میں روح القدس کے ذریعے پھیلتی ہے جو ہمیں دیا گیا ہے۔\n6۔ کیونکہ جب ہم ابھی طاقت سے محروم تھے، تو وقت پر مسیح بے دینوں کے لیے جان دے گئے۔ {وقت پر: یا، وقت کے مطابق}\n7۔ کیونکہ شاذ و نادر ہی کوئی نیک انسان مر سکتا ہے: پھر بھی ایک اچھے آدمی کے لیے کچھ لوگ مرنے کی جرات بھی کریں گے۔\n8۔ لیکن خدا نے ہم سے اپنی محبت کا اظہار کیا، کہ جب ہم ابھی گناہ گار تھے، مسیح نے ہمارے لیے جان دی۔\n9۔ اس سے بھی زیادہ، اب جب کہ ہم اس کے خون سے راستباز ہیں، تو ہم اس کے ذریعے غصے سے بچ جائیں گے۔\n10۔ کیونکہ اگر جب ہم دشمن تھے، تو اس کے بیٹے کی موت سے ہم خدا سے صلح کر لیتے، اور اس سے بھی بڑھ کر، ہم اس کی جان سے نجات پائیں گے۔\n11۔ اور نہ صرف {یہ}، بلکہ ہم اپنے خداوند یسوع مسیح کے ذریعے خدا میں خوشی بھی محسوس کرتے ہیں، جس کے ذریعے ہم نے اب کفارہ حاصل کیا ہے۔ {کفارہ: یا، مصالحت}\n12۔ اسی لیے، جیسے ایک شخص کے ذریعے گناہ دنیا میں آیا، اور موت گناہ سے؛ اور یوں موت سب انسانوں پر گزری، کیونکہ سب نے گناہ کیا ہے: {اس کے لیے: یا، کس میں}\n13۔ (کیونکہ جب تک قانون گناہ دنیا میں نہیں تھا: لیکن گناہ اس وقت نہیں لگایا جاتا جب کوئی قانون نہ ہو۔\n14. پھر بھی موت آدم سے موسیٰ تک حکمرانی کرتی رہی، حتیٰ کہ ان پر بھی جنہوں نے آدم کی گناہ کی مثال کے بعد گناہ نہیں کیا تھا، جو آنے والے شخص کی علامت ہے۔\n15. لیکن جرم کے طور پر نہیں، مفت تحفہ بھی ہے۔ کیونکہ اگر ایک کے گناہ کی وجہ سے بہت سے لوگ مر جائیں، تو خدا کا فضل اور فضل کا تحفہ، جو کہ ایک شخص، یسوع مسیح کی طرف سے دیا گیا ہے، بہت سے لوگوں کو ملا ہے۔\n16. اور نہ کہ جیسے {گناہ گار} نے کیا، {ویسے} تحفہ بھی ہے: کیونکہ فیصلہ {تھا} ایک کے ہاتھوں ملامت کے لیے، بلکہ مفت تحفہ {ہے} جو کئی گناہوں کا راستبازی کا باعث بنتا ہے۔\n17۔ کیونکہ اگر ایک شخص کے جرم سے موت کا حکم ہو؛ اس سے کہیں زیادہ جو فضل اور راستبازی کا تحفہ حاصل کرتے ہیں، وہ زندگی میں ایک کے ذریعے حکومت کریں گے، یسوع مسیح۔) {ایک آدمی کی...: یا، ایک جرم کی وجہ سے}\n18. لہٰذا جیسا کہ ایک {فیصلہ آیا} کے جرم کی وجہ سے تمام انسانوں پر سزا دی گئی؛ اسی طرح ایک کی راستبازی سے {جو مفت تحفہ ملا} تمام انسانوں کو زندگی کی جواز کے لیے ملا۔ {جرم کی وجہ سے...: یا، ایک جرم کی وجہ سے} {راستبازی کے ذریعے...: یا، ایک راستبازی کے ذریعے}\n19۔ جیسے ایک شخص کی نافرمانی سے بہت سے لوگ گناہ گار بنائے، ویسے ہی ایک کی اطاعت سے بہت سے نیک بنتے ہیں۔\n20۔ مزید یہ کہ قانون نے یہ بھی کہا کہ جرم عام ہو سکتا ہے۔ لیکن جہاں گناہ زیادہ تھا، وہاں فضل اور بھی زیادہ تھا:\n21. تاکہ جیسے گناہ موت تک حکمرانی کرتا رہا، ویسے ہی فضل راستبازی کے ذریعے یسوع مسیح ہمارے رب کے ذریعے ابدی زندگی تک حکمرانی کرے۔","1. پھر ہم کیا کہیں؟ کیا ہم گناہ میں جاری رہیں، تاکہ فضل کی بھرمار ہو؟\n2. خدا نہ کرے۔ ہم، جو گناہ سے مر چکے ہیں، وہاں کیسے زندہ رہیں گے؟\n3۔ کیا آپ نہیں جانتے کہ ہم میں سے اتنے لوگ جو یسوع مسیح میں بپتسمہ لے چکے تھے، وہ اس کی موت تک بپتسمہ بھی لیے گئے؟ {تھے: یا، ہیں}\n4۔ اسی لیے ہم اس کے ساتھ موت میں بپتسمہ دے کر دفن ہوتے ہیں: جیسے مسیح باپ کی جلال سے مردوں میں سے زندہ ہوا، ویسے ہی ہمیں بھی نئی زندگی میں چلنا چاہیے۔\n5۔ کیونکہ اگر ہم اس کی موت کی صورت میں ایک ساتھ بٹھائے گئے ہیں، تو ہم بھی {اس کی} قیامت کی مشابہت میں ہوں گے:\n6۔ یہ جانتے ہوئے، کہ ہمارا بوڑھا آدمی {وہ} کے ساتھ مصلوب کیا گیا ہے، تاکہ گناہ کا جسم تباہ ہو جائے، اور اب سے ہم گناہ کی خدمت نہ کریں۔\n7۔ جو مر چکا ہے وہ گناہ سے آزاد ہے۔ {آزاد: Gr. justified}\n8۔ اب اگر ہم مسیح کے ساتھ مردہ ہیں، تو ہم ایمان رکھتے ہیں کہ ہم بھی اس کے ساتھ جییں گے:\n9۔ یہ جانتے ہوئے کہ مسیح جو مردوں میں سے زندہ ہو رہا ہے وہ اب نہیں مرتا؛ موت اب اس پر کوئی حکمرانی نہیں رکھتی۔\n10۔ کیونکہ جس میں وہ مرا، وہ ایک بار گناہ کی وجہ سے مرا؛ لیکن جس طرح وہ زندہ ہے، وہ خدا کے لیے زندہ ہے۔\n11۔ اسی طرح آپ خود کو بھی گناہ کے لیے مردہ سمجھتے ہیں، بلکہ یسوع مسیح ہمارے رب کے ذریعے خدا کے لیے زندہ ہیں۔\n12۔ لہٰذا گناہ کو اپنے فانی جسم میں حکمرانی نہ کرے، تاکہ تم اس کی خواہشات میں اس کی اطاعت کرو۔\n13۔ اپنے ارکان کو گناہ کے لیے ناانصافی کے اوزار کے طور پر نہ چھوڑو، بلکہ خدا کے سامنے سر تسلیم کرو، جیسے زندہ لوگ مردوں میں سے زندہ ہیں، اور اپنے ارکان خدا کے سامنے راستبازی کے اوزار بن جاؤ۔ {آلات: Gr. arms, or, weapons}\n14۔ کیونکہ گناہ تم پر حاوی نہیں ہوگا: کیونکہ تم قانون کے تحت نہیں بلکہ فضل کے تحت ہو۔\n15۔ پھر کیا؟ کیا ہم گناہ کریں، کیونکہ ہم قانون کے تحت نہیں بلکہ فضل کے تحت ہیں؟ خدا نہ کرے۔\n16۔ تم نہیں جانتے کہ جن کے سامنے تم خود کو غلام بناتے ہو، تم اس کے بندوں کی اطاعت کرتے ہو؛ کیا موت تک گناہ کا ہے، یا راستبازی کی اطاعت کا؟\n17. لیکن خدا کا شکر ہے کہ تم گناہ کے خادم تھے، لیکن تم نے دل سے اس عقیدے کی پیروی کی جو تمہیں نجات دی گئی تھی۔ {جو...: Gr. جہاں تم پہنچائے گئے تھے}\n18۔ پھر گناہ سے آزاد ہو کر، تم راستبازی کے خادم بن گئے۔\n19۔ میں انسانوں کی طرح بولتا ہوں کیونکہ تمہارے جسم کی کمزوری ہے: کیونکہ تم نے اپنے لوگوں کو ناپاکی اور گناہ کو گناہی کے حوالے کیا؛ اسی طرح، اب اپنے افراد کو راستبازی کے حوالے کرو، پاکیزگی کے حوالے کرو۔\n20۔ کیونکہ جب تم گناہ کے خادم تھے، تو تم راستبازی سے آزاد تھے۔ {سے...: Gr. سے راستبازی تک}\n21۔ تب ان چیزوں میں کون سا پھل تھا جن پر تم اب شرمندہ ہو؟ کیونکہ ان چیزوں کا اختتام موت ہے۔\n22. لیکن اب جب آپ گناہ سے آزاد ہو گئے ہیں اور خدا کے خادم بن گئے ہیں، تو آپ کے پھل پاکیزگی اور دائمی زندگی کے لیے ہیں۔\n23۔ گناہ کی مزدوری {ہے} موت کے لیے؛ لیکن خدا کا تحفہ یسوع مسیح ہمارے رب کے ذریعے ابدی زندگی ہے۔","1۔ بھائیو، کیا تم نہیں جانتے (کیونکہ میں شریعت جاننے والوں سے بات کرتا ہوں) کہ شریعت انسان پر کیسے حکمرانی کرتی ہے جب تک وہ زندہ ہے؟\n2۔ کیونکہ جس عورت کا شوہر ہے وہ قانون کے تحت اپنے شوہر کی پابند ہے جب تک وہ زندہ ہے؛ لیکن اگر شوہر فوت ہو جائے تو وہ اپنے شوہر کے قانون سے آزاد ہو جاتی ہے۔\n3۔ تو اگر جب تک اس کا شوہر زندہ ہے، وہ کسی اور مرد سے شادی شدہ ہو، تو اسے کہا جائے گا: لیکن اگر اس کا شوہر مر چکا ہو تو وہ اس قانون سے آزاد ہے؛ تاکہ وہ بدکار نہ ہو، چاہے وہ کسی اور مرد سے شادی شدہ ہو۔\n4۔ اسی لیے، میرے بھائیو، تم بھی مسیح کے جسم کے ذریعے شریعت کے لیے مردہ ہو گئے ہو؛ کہ تم کسی اور سے شادی کرو، {حتیٰ کہ} اس سے جو مردوں میں سے زندہ ہوا، تاکہ ہم خدا کے لیے پھل دیں۔\n5۔ کیونکہ جب ہم جسم میں تھے، تو گناہوں کی حرکتیں، جو قانون کے مطابق تھیں، ہمارے ارکان میں موت تک پھل لانے کے لیے کام کرتی تھیں۔ {موشنز: گری۔ پیشنز}\n6۔ لیکن اب ہم شریعت سے نجات پا چکے ہیں، جو مردہ ہے جس میں ہمیں قید کیا گیا تھا؛ کہ ہمیں نئی روح میں خدمت کرنی چاہیے، نہ کہ حرف کی پرانی حالت میں۔ {جو ہے...: یا، اس کے لیے مردہ ہونا}\n7. پھر ہم کیا کہیں؟ {کیا} قانون گناہ ہے؟ خدا نہ کرے۔ نہیں، میں نے گناہ نہیں جانا تھا، بلکہ شریعت کے ذریعے: کیونکہ میں نے ہوس کو نہیں جانا تھا، سوائے اس کے کہ شریعت نے کہا تھا، تو لالچ نہ کرو۔ {ہوس: یا، لذت بھر}\n8۔ لیکن گناہ نے، حکم کے تحت، میرے اندر ہر طرح کی لذت پیدا کی۔ کیونکہ قانون کے بغیر گناہ مر چکا تھا۔\n9۔ کیونکہ میں ایک بار قانون کے بغیر زندہ تھا: لیکن جب حکم آیا، تو گناہ دوبارہ زندہ ہوا، اور میں مر گیا۔\n10۔ اور وہ حکم، جو زندگی کے لیے مقرر کیا گیا تھا، میں نے پایا کہ وہ موت تک ہے۔\n11۔ کیونکہ گناہ نے، حکم کے ذریعے موقع پر مجھے دھوکہ دیا، اور اس سے مجھے مار ڈالا۔\n12۔ اسی لیے شریعت مقدس ہے، اور حکم مقدس، منصفانہ اور نیک ہے۔\n13۔ تو کیا جو اچھا ہے وہ میرے لیے موت بنا؟ خدا نہ کرے۔ بلکہ گناہ، تاکہ یہ گناہ نظر آئے، جو میرے اندر موت کا کام کر رہا ہے اس چیز سے جو اچھا ہے؛ کہ حکم کے تحت گناہ حد سے زیادہ گناہ بن سکتا ہے۔\n14۔ کیونکہ ہم جانتے ہیں کہ شریعت روحانی ہے: لیکن میں جسمانی ہوں، گناہ کے تحت بیچا گیا ہوں۔\n15۔ جو کچھ میں کرتا ہوں اس کے لیے میں اجازت نہیں دیتا: جو میں چاہتا ہوں، جو میں نہیں کرتا؛ لیکن جو چیز مجھے ناپسند ہے، وہ میں کرتا ہوں۔ {اجازت دیں: Gr. جانیں}\n16۔ اگر پھر میں وہ کام کروں جو میں نہیں کروں گا، تو میں اس قانون کو قبول کرتا ہوں کہ {یہ} اچھا ہے۔\n17۔ تو پھر میں نہیں جو یہ سب کرتا ہوں، بلکہ گناہ ہی میرے اندر بستا ہے۔\n18۔ کیونکہ میں جانتا ہوں کہ میرے اندر (یعنی میرے جسم میں) کوئی اچھی چیز نہیں ہے: کیونکہ مرضی میرے ساتھ موجود ہے؛ لیکن {کیسے} وہ کیا جائے جو اچھا ہے، میں نہیں دیکھتا۔\n19. جس بھلائی کے لیے میں چاہتا ہوں، میں نہیں کرتا: بلکہ وہ برائی جو میں نہیں کرنا چاہتا، جو میں کرتا ہوں۔\n20۔ اب اگر میں یہ کروں گا تو میں نہیں کروں گا، اب میں نہیں ہوں گا جو یہ کروں گا، بلکہ وہ گناہ ہے جو میرے اندر بستا ہے۔\n21۔ پھر میں ایک قانون پاتا ہوں کہ جب میں اچھا کرنا چاہتا ہوں تو برائی میرے ساتھ موجود ہوتی ہے۔\n22. کیونکہ میں اپنے اندر موجود انسان کے بعد خدا کے قانون سے خوش ہوں:\n23. لیکن میں اپنے ارکان میں ایک اور قانون دیکھتا ہوں، جو میرے ذہن کے قانون کے خلاف جنگ کر رہا ہے، اور مجھے گناہ کے قانون کے قید میں لے جا رہا ہے جو میرے ارکان میں ہے۔\n24. اے بدبخت آدمی جو میں ہوں! کون مجھے اس موت کے جسم سے بچائے گا؟ {جسم...: یا، یہ موت کا جسم}\n25۔ میں خدا کا شکر ادا کرتا ہوں یسوع مسیح ہمارے رب کے ذریعے۔ تو پھر ذہن کے ساتھ میں خود خدا کے قانون کی خدمت کرتا ہوں؛ لیکن جسم کے ساتھ گناہ کا قانون۔","1. لہٰذا اب ان لوگوں پر کوئی سزا نہیں جو مسیح یسوع میں ہیں، جو جسم کے پیچھے نہیں بلکہ روح کے پیچھے چلتے ہیں۔\n2. کیونکہ یسوع مسیح میں روح حیات کے قانون نے مجھے گناہ اور موت کے قانون سے آزاد کر دیا ہے۔\n3۔ جو قانون نہیں کر سکا، کیونکہ وہ جسم کے ذریعے کمزور تھا، خدا نے اپنے بیٹے کو گناہ گار گوشت کی صورت میں بھیجا، اور گناہ کے لیے جسم میں گناہ کی سزا دی: {گناہ کے لیے: یا، گناہ کے لیے قربانی کے ذریعے}\n4۔ تاکہ قانون کی راستبازی ہم میں پوری ہو، جو جسم کے پیچھے نہیں بلکہ روح کی پیروی کرتے ہیں۔\n5۔ کیونکہ جو جسم کے پیچھے ہیں وہ جسم کی چیزوں کی پرواہ کرتے ہیں؛ لیکن جو روح کے پیچھے ہیں وہ روح کی چیزیں ہیں۔\n6۔ کیونکہ جسمانی ارادے میں مبتلا ہونا {ہے} موت؛ لیکن روحانی ذہن ہونا زندگی اور سکون ہے۔ {جسمانی ہونا...: Gr. جسم کی دیکھ بھال} {روحانی طور پر...: Gr. روح کی ذہانت}\n7۔ کیونکہ جسمانی ذہن خدا کے خلاف دشمنی ہے: کیونکہ وہ خدا کے قانون کے تابع نہیں ہے، اور نہ ہی ہو سکتا۔ {جسمانی...: Gr. جسم کی دیکھ بھال}\n8۔ تو جو لوگ جسمانی طور پر ہیں وہ خدا کو خوش نہیں کر سکتے۔\n9۔ لیکن آپ جسم میں نہیں بلکہ روح میں ہیں، اگر ایسا ہے کہ خدا کی روح آپ میں رہتی ہے۔ اب اگر کسی کے پاس مسیح کی روح نہیں ہے، تو وہ اس کا نہیں ہے۔\n10۔ اور اگر مسیح آپ میں ہے، تو جسم گناہ کی وجہ سے مردہ ہے؛ لیکن روح {ہے} زندگی راستبازی کی وجہ سے۔\n11. لیکن اگر جس نے یسوع کو مردوں میں سے زندہ کیا اس کی روح تم میں رہتی ہے، تو جس نے مسیح کو مردوں میں سے زندہ کیا، وہ بھی تمہارے فانی جسموں کو اپنی روح کے ذریعے زندہ کرے گا جو تم میں بستا ہے۔ {بذریعہ: یا، وجہ سے}\n12. لہٰذا، بھائیو، ہم جسم کے مقروض نہیں بلکہ جسم کے بعد زندہ رہنے کے لیے ہیں۔\n13۔ کیونکہ اگر تم جسم کے بعد زندہ رہو گے تو مر جاؤ گے: لیکن اگر تم روح کے ذریعے جسم کے اعمال کو ذلیل کرو گے تو زندہ رہو گے۔\n14. جتنے لوگ خدا کی روح کی رہنمائی میں ہیں، وہ خدا کے بیٹے ہیں۔\n15۔ کیونکہ تم نے دوبارہ خوف کے لیے غلامی کی روح نہیں پائی؛ لیکن تم نے گود لینے کی روح حاصل کر لی ہے، جس کے ذریعے ہم پکار رہے ہیں، ابا، باپ۔\n16۔ روح خود ہماری روح سے گواہی دیتا ہے کہ ہم خدا کے بچے ہیں:\n17۔ اور اگر بچے ہوں تو وارث؛ خدا کے وارث، اور مسیح کے ساتھ مشترکہ وارث؛ اگر ایسا ہے تو ہم {اس کے ساتھ} تکلیفیں اٹھائیں، تاکہ ہم بھی مل کر جلال حاصل کر سکیں۔\n18۔ کیونکہ میں سمجھتا ہوں کہ اس وقت کی تکالیف {موازنہ کے لائق نہیں ہیں} اس جلال کے ساتھ جو ہم میں ظاہر ہوگی۔\n19۔ کیونکہ مخلوق کی مخلص توقع خدا کے بیٹوں کے ظہور کا انتظار کر رہی ہے۔\n20۔ کیونکہ مخلوق کو غرور کے تابع کیا گیا، نہ کہ اپنی مرضی سے، بلکہ اس کی وجہ سے جس نے {یہی} امید میں تابع کی،\n21۔ کیونکہ مخلوق خود بھی فساد کی غلامی سے آزاد ہو کر خدا کے بچوں کی شاندار آزادی میں آئے گی۔\n22۔ کیونکہ ہم جانتے ہیں کہ پوری مخلوق اب تک ایک ساتھ کراہتی اور تکلیف میں مبتلا ہے۔ {the...: یا، ہر مخلوق}\n23. اور نہ صرف {وہ}، بلکہ ہم بھی، جن کے پاس روح کے پہلے پھل ہیں، حتیٰ کہ ہم خود بھی اپنے اندر کراہتے ہیں، اپنے جسم کی گود لینے کے انتظار میں، {یعنی}، نجات کے لیے۔\n24۔ کیونکہ ہم امید سے نجات پاتے ہیں: لیکن جو امید نظر آتی ہے وہ امید نہیں ہوتی: کیونکہ انسان جو غصہ دکھاتا ہے، وہ پھر بھی کیوں امید رکھتا ہے؟\n25۔ لیکن اگر ہم امید کرتے ہیں کہ ہمیں نظر نہیں آتا، {تو} صبر کے ساتھ انتظار کرتے ہیں۔\n26۔ اسی طرح روح ہماری کمزوریوں میں بھی مدد کرتا ہے: کیونکہ ہم نہیں جانتے کہ ہمیں کس چیز کے لیے دعا کرنی چاہیے، بلکہ روح خود ہمارے لیے ایسی کراہتوں سے شفاعت کرتا ہے جو کہی نہیں جا سکتیں۔\n27۔ اور جو دلوں کی تلاش کرتا ہے وہ جانتا ہے کہ روح کا ذہن کیا ہے، کیونکہ وہ مقدسین کے لیے خدا کی مرضی کے مطابق شفاعت کرتا ہے۔ {کیونکہ: یا، وہ}\n28۔ اور ہم جانتے ہیں کہ سب چیزیں مل کر بھلائی کے لیے کام کرتی ہیں، ان لوگوں کے لیے جو خدا سے محبت کرتے ہیں، ان کے لیے جو {اس کے} مقصد کے مطابق بلائے گئے ہیں۔\n29۔ جس کے لیے وہ پہلے سے جانتا تھا، اس نے یہ بھی مقدر کیا تھا کہ وہ اپنے بیٹے کی شبیہ کے مطابق ہو، تاکہ وہ بہت سے بھائیوں میں سب سے بڑا ہو۔\n30۔ مزید یہ کہ جنہیں اس نے پہلے سے مقرر کیا، انہیں بھی بلایا: اور جنہیں بلایا، انہیں بھی جائز قرار دیا: اور جنہیں اس نے راستباز بنایا، انہیں بھی جلال بخشا۔\n31۔ پھر ہم ان باتوں کے بارے میں کیا کہیں؟ اگر خدا ہمارے لیے ہے، تو ہمارے خلاف کون ہو سکتا ہے؟\n32۔ جس نے اپنے بیٹے کو معاف نہیں کیا، بلکہ اسے ہم سب کے لیے دے دیا، وہ کیسے اس کے ساتھ ہمیں سب کچھ مفت دے سکتا ہے؟\n33۔ کون کسی چیز کو خدا کے منتخب کردہ پر ڈالے گا؟ {یہ ہے} خدا جو انصاف کرتا ہے۔\n34۔ وہ کون ہے جو سزا دیتا ہے؟ {یہ ہے} مسیح جو مر گیا، جی ہاں، جو دوبارہ زندہ ہوا، جو خدا کے دائیں ہاتھ پر بھی ہے، جو ہمارے لیے بھی شفاعت کرتا ہے۔\n35۔ ہمیں مسیح کی محبت سے کون جدا کرے گا؟ کیا مصیبت، یا مصیبت، یا ظلم و ستم، یا قحط، یا برہنگی ہونا، یا خطرہ، یا تلوار؟\n36۔ جیسا کہ لکھا ہے، تیری خاطر ہم سارا دن مارے جاتے ہیں؛ ہمیں ذبح کے لیے بھیڑیں شمار کیا جاتا ہے۔\n37۔ نہیں، ان سب چیزوں میں ہم اس کے ذریعے فاتح نہیں ہیں جس نے ہم سے محبت کی۔\n38۔ کیونکہ میں قائل ہوں کہ نہ موت، نہ زندگی، نہ فرشتے، نہ ریاستیں، نہ طاقتیں، نہ موجودہ چیزیں، نہ آنے والی چیزیں،\n39۔ نہ اونچائی، نہ گہرائی، اور نہ ہی کوئی اور مخلوق، ہمیں خدا کی محبت سے جدا نہیں کر سکتی، جو مسیح یسوع ہمارے رب میں ہے۔","1. میں مسیح میں سچائی کہتا ہوں، میں جھوٹ نہیں بولتا، میرا ضمیر بھی روح القدس میں گواہی دے رہا ہے،\n2۔ کہ میرے دل میں بہت بھاری اور مسلسل غم ہے۔\n3۔ کیونکہ میں چاہتا تھا کہ میں مسیح کی طرف سے اپنے بھائیوں، میرے رشتہ داروں کے لیے ہو، جسم کے مطابق: {لعنتی: یا، جدا}\n4. بنی اسرائیل کون ہیں؛ جس کے لیے گود لینا، جلال، وعدے، قانون دینا، خدا کی خدمت اور وعدے شامل ہیں؛ {معاہدے: یا، وصیت}\n5۔ جن کے باپ ہیں، اور جن کے جسم کے بارے میں مسیح {آیا}، جو سب سے اوپر، خدا ہمیشہ کے لیے بابرکت ہے۔ آمین۔\n6۔ ایسا نہیں کہ خدا کا کلام کوئی اثر نہیں ہوا۔ کیونکہ وہ سب اسرائیل نہیں ہیں، جو اسرائیل کے ہیں:\n7۔ نہ ہی نہیں، کیونکہ وہ ابراہیم کی نسل ہیں، {کیا وہ سب بچے ہیں}: لیکن تمہاری نسل اسحاق میں پکارے گی۔\n8۔ یعنی، جو جسم کے بچے ہیں، وہ خدا کے بچے نہیں بلکہ وعدے کے بچے بیج کے طور پر شمار کیے جاتے ہیں۔\n9۔ کیونکہ یہ وعدے کا وعدہ ہے، اس وقت میں آؤں گا، اور سارہ کا بیٹا ہوگا۔\n10۔ اور صرف {یہ} نہیں؛ بلکہ جب ربیکا نے بھی ایک سے حاملہ ہوئی، {حتیٰ کہ} ہمارے والد اسحاق سے؛\n11۔ (کیونکہ {بچے} ابھی پیدا نہیں ہوئے، نہ ہی کوئی اچھا یا برائی کیا ہے، تاکہ خدا کا مقصد انتخاب کے مطابق اعمال کا نہیں بلکہ اس کے لیے ہو سکتا ہے جو پکارتا ہے؛)\n12۔ اس سے کہا گیا، بڑا چھوٹے کی خدمت کرے گا۔ {بزرگ: یا، اس سے بھی زیادہ} {چھوٹا: یا، چھوٹا}\n13۔ جیسا کہ لکھا ہے، یعقوب میں نے محبت کی، لیکن عیسو سے میں نے نفرت کی۔\n14۔ پھر ہم کیا کہیں؟ کیا خدا کے ساتھ کوئی ناانصافی ہے؟ خدا نہ کرے۔\n15۔ کیونکہ وہ موسیٰ سے کہتا ہے، میں جس پر رحم کروں گا اس پر رحم کروں گا، اور جس پر رحم کروں گا اس پر رحم کروں گا۔\n16. تو پھر یہ اس کی نہیں ہے جو چاہتا ہے، نہ بھاگنے والے سے، بلکہ خدا کی طرف سے ہے جو رحم دکھاتا ہے۔\n17۔ کیونکہ کتاب فرعون سے کہتی ہے، اسی مقصد کے لیے میں نے تمہیں اٹھایا ہے تاکہ میں اپنی طاقت دکھاؤں اور میرا نام زمین بھر میں پکارا جائے۔\n18۔ اسی لیے وہ جس پر رحم کرنا چاہتا ہے اور جسے چاہے سخت کرتا ہے۔\n19۔ پھر تم مجھ سے کہو گے، وہ ابھی تک عیب کیوں ڈھونڈ رہا ہے؟ کیونکہ کس نے اس کی مرضی کی مزاحمت کی؟\n20۔ نہیں، اے انسان، تم کون ہو جو خدا کے خلاف جواب دیتا ہے؟ کیا وہ چیز جو بنائی وہ اس سے کہے گی جس نے اسے بنایا ہے، تو نے مجھے ایسا کیوں بنایا؟ {جواب...: یا، پھر جواب دیں، یا، خدا سے جھگڑ؟}\n21. کیا مٹی کے کونے والے کو ایک برتن عزت کے لیے اور دوسرے کو بے عزتی بنانے کا اختیار نہیں؟\n22۔ {کیا} اگر خدا، جو [اپنی} غضب دکھانے اور اپنی طاقت ظاہر کرنے کے لیے تیار ہو، بہت صبر کے ساتھ تباہی کے لیے تیار کیے گئے غضب کے برتنوں کو برداشت کرے: {موزوں: یا، بنائے گئے}\n23۔ تاکہ وہ اپنی عظمت کی دولت کو رحمت کے برتنوں پر ظاہر کرے، جنہیں اس نے پہلے جلال کے لیے تیار کیا تھا،\n24۔ یہاں تک کہ ہم بھی، جنہیں اس نے بلایا ہے، صرف یہودیوں سے نہیں بلکہ غیر یہودیوں سے بھی؟\n25۔ جیسا کہ وہ اوسی میں بھی کہتا ہے، میں انہیں اپنی قوم کہوں گا، جو میرے لوگ نہیں تھے؛ اور اس کا محبوب، جو محبوب نہیں تھا۔\n26۔ اور یہ اس جگہ ہوگا جہاں انہیں کہا گیا تھا، تم میرے لوگ نہیں ہو؛ وہاں انہیں زندہ خدا کے بچے کہا جائے گا۔\n27۔ یسعیاس اسرائیل کے بارے میں بھی پکار رہا ہے، اگرچہ بنی اسرائیل کی تعداد سمندر کی ریت کی طرح ہے، لیکن ایک باقیات بچائی جائیں گی:\n28۔ کیونکہ وہ کام مکمل کرے گا، اور راستبازی میں اسے مختصر کرے گا: کیونکہ خداوند زمین پر ایک مختصر کام کرے گا۔ {کام: یا، اکاؤنٹ}\n29۔ اور جیسا کہ عیسیٰ نے پہلے کہا، جب تک سباوت کے رب نے ہمیں ایک بیج نہ چھوڑا ہو، ہم سڈوما کی طرح تھے، اور عمورہ کی طرح بنائے گئے تھے۔ {سباؤتھ: عبرانی۔ میزبان}\n30۔ پھر ہم کیا کہیں؟ کہ غیر یہودی، جو راستبازی کے پیچھے نہیں گئے، راستبازی تک پہنچ چکے ہیں، حتیٰ کہ وہ راستبازی جو ایمان کی ہے۔\n31۔ لیکن اسرائیل، جو راستبازی کے قانون کی پیروی کرتا ہے، راستبازی کے قانون تک نہیں پہنچا۔\n32۔ کیوں؟ کیونکہ {انہوں نے اسے مانا} ایمان سے نہیں، بلکہ قانون کے اعمال کے ذریعے تلاش کیا۔ کیونکہ وہ اس پتھر پر ٹھوکر کھا گئے؛\n33۔ جیسا کہ لکھا ہے، دیکھو، میں سیون میں ایک پتھر اور جرم کا پتھر رکھتا ہوں: اور جو بھی اس پر ایمان رکھے گا وہ شرمندہ نہیں ہوگا۔ {شرمندہ: یا الجھن میں}","1۔ بھائیو، میرے دل کی دعا اور خدا سے اسرائیل کے لیے دعا ہے کہ وہ نجات پائیں۔\n2۔ کیونکہ میں انہیں یہ نوٹ دیتا ہوں کہ ان میں خدا کا جوش ہے، لیکن علم کے مطابق نہیں۔\n3۔ کیونکہ وہ خدا کی راستبازی سے لاعلم ہیں، اور اپنی راستبازی قائم کرنے کی کوشش کر رہے ہیں، انہوں نے خود کو خدا کی راستبازی کے حوالے نہیں کیا۔\n4۔ کیونکہ مسیح ہر ایمان رکھنے والے کے لیے راستبازی کے لیے شریعت کا اختتام ہے۔\n5۔ کیونکہ موسیٰ نے شریعت کی راستبازی بیان کی ہے، کہ جو انسان یہ کام کرے گا وہ ان پر عمل کرے گا۔\n6۔ لیکن جو راستبازی ایمان کی ہے وہ اس حکمت سے کہتی ہے، اپنے دل میں مت کہو، کون آسمان پر چڑھے گا؟ (یعنی، مسیح کو اوپر سے گرانا:)\n7۔ یا، کون گہرائی میں اترے گا؟ (یعنی، مسیح کو مردوں میں سے دوبارہ زندہ کرنا۔)\n8۔ لیکن یہ کیا کہتا ہے؟ کلام تمہارے قریب ہے، {حتیٰ کہ} تمہارے منہ میں اور تمہارے دل میں: یعنی، ایمان کا کلام جو ہم تبلیغ کرتے ہیں؛\n9۔ کہ اگر تم اپنے منہ سے خداوند یسوع کا اقرار کرو، اور اپنے دل میں ایمان رکھو کہ خدا نے اسے مردوں میں سے زندہ کیا ہے، تو تم نجات پاؤ گے۔\n10۔ کیونکہ دل سے انسان راستبازی پر ایمان رکھتا ہے؛ اور منہ سے نجات کا اعتراف کیا جاتا ہے۔\n11۔ کیونکہ کتاب مقدس کہتی ہے، جو اس پر ایمان لائے گا وہ شرمندہ نہیں ہوگا۔\n12۔ کیونکہ یہودی اور یونانی میں کوئی فرق نہیں: کیونکہ ایک ہی رب سب کے لیے امیر ہے جو اسے پکارتے ہیں۔\n13۔ کیونکہ جو بھی خداوند کے نام کو پکارے گا وہ نجات پائے گا۔\n14۔ تو پھر وہ اس سے کیسے پکاریں گے جس پر انہوں نے ایمان نہیں رکھا؟ اور وہ اس پر کیسے یقین کریں گے جس کے بارے میں انہوں نے نہیں سنا؟ اور وہ بغیر مبلغ کے کیسے سنیں گے؟\n15۔ اور وہ کیسے تبلیغ کریں گے، جب تک کہ انہیں بھیجا نہ جائے؟ جیسا کہ لکھا ہے، ان کے قدم کتنے خوبصورت ہیں جو امن کی خوشخبری سناتے ہیں اور خوشخبری دیتے ہیں!\n16۔ لیکن سب نے انجیل کی اطاعت نہیں کی۔ کیونکہ عیسیاس فرماتا ہے، اے خداوند، کس نے ہماری خبر پر یقین کیا؟ {ہماری رپورٹ: ہماری سماعت؟} {رپورٹ: یا، تبلیغ؟}\n17۔ تو ایمان سن کر آتا ہے، اور خدا کے کلام سے سننا۔\n18۔ لیکن میں کہتا ہوں، کیا انہوں نے نہیں سنا؟ ہاں، ان کی آواز پوری زمین تک پہنچی، اور ان کے الفاظ دنیا کے کناروں تک پہنچ گئے۔\n19۔ لیکن میں کہتا ہوں، کیا اسرائیل کو معلوم نہیں تھا؟ سب سے پہلے موسیٰ کہتا ہے، میں تمہیں ان لوگوں سے حسد میں مبتلا کروں گا جو لوگ نہیں ہیں، اور ایک بے وقوف قوم سے تمہیں ناراض کروں گا۔\n20۔ لیکن یسیاس بہت دلیر ہے، اور کہتا ہے، میں ان میں سے پایا گیا جنہوں نے مجھے نہیں ڈھونڈا؛ مجھے ان کے سامنے ظاہر کیا گیا جنہوں نے میرے بارے میں نہیں پوچھا۔\n21۔ لیکن وہ اسرائیل سے کہتا ہے، سارا دن میں نے نافرمان اور نافرمان قوم کے لیے ہاتھ پھیلائے ہیں۔","1۔ میں کہتا ہوں، کیا خدا نے اپنے لوگوں کو نکال دیا ہے؟ خدا نہ کرے۔ کیونکہ میں بھی اسرائیلی ہوں، ابراہیم کی نسل سے، جو بنیامین کے قبیلے سے ہے۔\n2۔ خدا نے اپنے لوگوں کو نہیں چھوڑا جنہیں وہ پہلے سے جانتا تھا۔ کیا تم نہیں جانتے کہ ایلیاس کے بارے میں کتاب مقدس کیا کہتی ہے؟ کیسے وہ اسرائیل کے خلاف خدا سے شفاعت کرتا ہے، کہتا ہے، {ایلیاس: یونانی الیاس میں؟}\n3۔ اے خداوند، انہوں نے تیرے نبیوں کو قتل کیا اور تیرے قربان گاہیں کھود دیں؛ اور میں اکیلا رہ جاتا ہوں، اور وہ میری جان چاہتے ہیں۔\n4۔ لیکن خدا کا جواب اس کے لیے کیا ہے؟ میں نے سات ہزار آدمی اپنے لیے محفوظ رکھے ہیں، جنہوں نے {بعل کی شبیہ} کے سامنے سر نہیں جھکایا۔\n5۔ پھر بھی، اس وقت بھی فضل کے انتخاب کے مطابق ایک باقیات موجود ہے۔\n6۔ اور اگر فضل سے تو پھر اعمال ختم ہو جائیں گے: ورنہ فضل اب فضل نہیں رہتا۔ لیکن اگر یہ اعمال کا ہے، تو پھر یہ فضل ختم ہو جائے گا: ورنہ کام کام ختم ہو جائے گا۔\n7. پھر کیا؟ اسرائیل نے وہ حاصل نہیں کیا جو وہ چاہتا ہے؛ لیکن انتخاب نے اسے حاصل کر لیا، اور باقی سب اندھے ہو گئے {اندھا: یا، سخت ہو گئے}\n8۔ (جیسا کہ لکھا ہے، خدا نے انہیں نیند کی روح دی ہے، آنکھیں جو وہ نہیں دیکھ سکتے، اور کان جو وہ نہیں سن سکتے؛) آج تک۔ {نیند: یا، پچھتاو}\n9۔ اور داؤد کہتا ہے، ان کی میز کو جال، جال، رکاوٹ اور ان کے لیے بدلہ بنایا جائے:\n10۔ ان کی آنکھیں گہری ہو جائیں تاکہ وہ نہ دیکھ سکیں، اور ہمیشہ اپنی پیٹھ جھک جائیں۔\n11۔ تو میں کہتا ہوں، کیا وہ لڑکھڑا گئے کہ انہیں گرنا چاہیے؟ خدا نہ کرے: بلکہ ان کے زوال کے ذریعے نجات غیر یہودیوں کے لیے آتی ہے، تاکہ انہیں حسد میں مبتلا کیا جا سکے۔\n12۔ اب اگر ان کا زوال دنیا کی دولت ہو، اور غیر قوموں کی دولت کم ہو جائے؛ ان کی مکمل حیثیت اور کتنی ہے؟ {کم ہوتا ہوا: یا، زوال، یا، نقصان}\n13۔ کیونکہ میں تم غیر یہودیو سے بات کرتا ہوں، چونکہ میں غیر یہودیوں کا رسول ہوں، میں اپنے کام کو بڑھا چڑھا کر پیش کرتا ہوں:\n14. اگر کسی بھی طرح میں اپنے جسم والوں کی تقلید پر اکسا سکوں اور کچھ کو بچا سکوں۔\n15. کیونکہ اگر ان کا نکالا {دنیا} کی صلح ہو، تو ان کا حصول {مردوں کی زندگی} کے علاوہ کیا ہوگا؟\n16۔ اگر پہلا پھل {ہو} مقدس ہے، تو گانٹھ {ہے} بھی {مقدس} ہے: اور اگر جڑ {ہو} مقدس ہے، تو شاخیں بھی {ہیں}۔\n17۔ اور اگر کچھ شاخیں ٹوٹ جائیں، اور تم، جو جنگلی زیتون کا درخت ہے، ان کے درمیان گراف کیا گیا ہو، اور ان کے ساتھ زیتون کے درخت کی جڑ اور چربی بھی شامل ہو؛ {ان میں: یا، ان کے لیے}\n18۔ شاخوں کے خلاف فخر نہ کرو۔ لیکن اگر تم فخر کرتے ہو، تو تم جڑ نہیں بلکہ جڑ اپنے ساتھ رکھتے ہو۔\n19۔ تب تم کہو گے، شاخیں توڑ دی گئیں تاکہ مجھے گراف کیا جائے۔\n20۔ خیر؛ کفر کی وجہ سے انہیں توڑ دیا گیا، اور تم ایمان پر قائم ہو۔ بلند خیال نہ رہیں، بلکہ خوف کریں:\n21. اگر خدا نے قدرتی شاخوں کو نہ بخشا، {ہوشیار رہو} کہیں وہ تمہیں بھی نہ بخشے۔\n22. تو خدا کی بھلائی اور سختی کو دیکھو: جو لوگ آئے، ان پر سختی آئے؛ لیکن تیری طرف، اچھائی، اگر تم اس کی بھلائی میں قائم رہو، ورنہ تم بھی کاٹ دیے جاؤ گے۔\n23۔ اور وہ بھی، اگر وہ کفر میں نہ رہیں، تو ان پر بھی گراف کیا جائے گا: کیونکہ خدا انہیں دوبارہ گراف کر سکتا ہے۔\n24۔ کیونکہ اگر تمہیں زیتون کے درخت سے کاٹا گیا جو فطری طور پر جنگلی ہے، اور قدرت کے خلاف ایک اچھے زیتون کے درخت میں گراف کیا گیا ہے، تو یہ جو قدرتی شاخیں ہیں، اپنے زیتون کے درخت میں اور کتنی بار کندہ کی جائیں گی؟\n25۔ کیونکہ بھائیو، میں نہیں چاہتا کہ تم اس راز سے لاعلم رہو، ورنہ تم اپنے غرور میں عقلمند ہو جاؤ؛ یہ اندھا پن جزوی طور پر اسرائیل کے ساتھ ہوتا ہے، جب تک کہ غیر قومیوں کی مکمل حیثیت نہ آ جائے۔ {اندھا: یا، سختی}\n26۔ اور یوں تمام اسرائیل نجات پائیں گے: جیسا کہ لکھا ہے، سیون سے نجات دہندہ نکلے گا، اور یعقوب سے بے دینی کو دور کرے گا:\n27۔ کیونکہ یہ میرا ان سے عہد ہے، جب میں ان کے گناہ ختم کروں گا۔\n28۔ جہاں تک انجیل کا تعلق ہے، {وہ تمہارے لیے} دشمن ہیں: لیکن انتخاب کے حوالے سے، {وہ} باپوں کی خاطر محبوب ہیں۔\n29۔ کیونکہ خدا کے تحفے اور پکار بغیر توبہ کے ہیں۔\n30۔ جیسا کہ آپ نے ماضی میں خدا پر ایمان نہیں لایا تھا، اب آپ نے ان کے کفر کے ذریعے رحمت حاصل کی ہے: {ایمان لے: یا، اطاعت کی}\n31۔ اسی طرح ان پر بھی اب یقین نہیں کیا گیا کہ آپ کی رحمت سے وہ بھی رحم حاصل کر سکتے ہیں۔ {یقین کیا: یا، اطاعت کی}\n32۔ کیونکہ خدا نے سب کو کفر میں مبتلا کر دیا ہے تاکہ وہ سب پر رحم کرے۔ {ختم...: یا، سب کو ایک ساتھ خاموش کر دو}\n33. اے خدا کی حکمت اور علم کی دولت کی گہرائی! کتنے ناقابل تلاش اس کے فیصلے ہیں، اور اس کے جاننے کے طریقے کتنے ناقابل تلاش ہیں!\n34۔ کیونکہ خداوند کے ذہن کو کون جانتا ہے؟ یا کون اس کا مشیر رہا ہے؟\n35۔ یا جس نے اسے سب سے پہلے دیا اور اسے واپس دیا جائے؟\n36۔ کیونکہ اس کے ذریعے، اس کے ذریعے، اور اس کے لیے سب کچھ ہے: جس کے لیے ہمیشہ جلال ہو۔ آمین۔ {جس نے: گری. وہ}","1. لہٰذا، بھائیو، خدا کی رحمت سے، میں آپ سے درخواست کرتا ہوں کہ آپ اپنے جسموں کو ایک زندہ قربانی پیش کریں، مقدس، خدا کے لیے قابل قبول، {یہ} آپ کی معقول خدمت ہے۔\n2۔ اور اس دنیا کے مطابق نہ بنیں: بلکہ اپنے ذہن کی تجدید سے تبدیل ہو جائیں، تاکہ آپ ثابت کر سکیں کہ خدا کی اچھی، قابل قبول اور کامل مرضی کیا ہے۔\n3۔ کیونکہ میں کہتا ہوں، اس فضل کے ذریعے جو مجھے دیا گیا ہے، ہر اس شخص کو جو آپ میں سے ہے، کہ خود کو اس سے زیادہ بلند نہ سمجھو جتنا اسے سوچنا چاہیے؛ بلکہ سنجیدگی سے سوچنا، جیسا کہ خدا نے ہر انسان کو ایمان کا پیمانہ دیا ہے۔ {سنجیدگی سے: Gr. to sobriety}\n4۔ چونکہ ہمارے پاس ایک ہی ادارے میں کئی ارکان ہیں، اور تمام ارکان کا عہدہ ایک جیسا نہیں ہے:\n5. تو ہم، {کثرت} ہونے کی وجہ سے، مسیح میں ایک جسم ہیں، اور ہر ایک دوسرے کا حصہ ہے۔\n6۔ پھر تحفے جو اس فضل کے مطابق مختلف ہوں جو ہمیں دیا گیا ہے، چاہے وہ پیش گوئی ہو، {ہم نبوت کریں} ایمان کے تناسب کے مطابق؛\n7۔ یا وزارت، {آئیے انتظار کریں} ہماری، خدمت پر: یا جو تعلیم دیتا ہے، تعلیم پر؛\n8۔ یا جو نصیحت کرتا ہے: جو دیتا ہے، {اسے سادگی سے کرنے دو}؛ جو محنت سے حکمرانی کرتا ہے؛ جو خوش دلی سے رحم دکھاتا ہے۔ {دو: یا، منتقل کرو} {سادگی کے ساتھ: یا، آزادانہ انداز میں}\n9۔ {محبت} بغیر دھوکہ دہی کے ہو۔ برائی سے نفرت کرو؛ جو اچھا ہے اس سے چمٹ جاؤ۔\n10۔ {بھائی چارے کی محبت کے ساتھ} ایک دوسرے سے محبت کریں؛ ایک دوسرے کو ترجیح دینے کی عزت میں؛ {ساتھ...: یا، بھائیوں کی محبت میں}\n11۔ کاروبار میں سست نہ ہو؛ جذبے سے بھرپور؛ خدا کی خدمت کرنا؛\n12۔ امید میں خوشی منانا؛ مصیبت میں مریض؛ دعا میں فورا جاری رکھنا؛\n13۔ مقدسین کی ضرورت کے مطابق تقسیم؛ مہمان نوازی کے لیے۔\n14۔ جو تمہیں ستاتے ہیں ان کو برکت دو: برکت دو، اور لعنت نہ دو۔\n15۔ ان کے ساتھ خوشی مناؤ جو خوش ہوتے ہیں، اور رونے والوں کے ساتھ روؤ۔\n16. {ایک ہی ذہن میں} ایک دوسرے کی طرف ہوں۔ اونچی باتوں کی پرواہ نہ کرو، بلکہ کم مرتبے والے لوگوں کے ساتھ حقارت کرو۔ اپنے ہی غرور میں عقل مند نہ ہوں۔ {حقارت سے...: یا، برے کاموں پر اکتفا کرنا}\n17. کسی کو برائی کا بدلہ نہ دیں۔ تمام مردوں کی نظر میں ایماندار چیزیں فراہم کریں۔\n18۔ اگر ممکن ہو، جتنا تم میں ہے، تو تمام مردوں کے ساتھ پرامن زندگی گزارو۔\n19۔ پیارے محبوبو، اپنے آپ کا بدلہ نہ لو، بلکہ غصے کی جگہ دو: کیونکہ لکھا ہے، انتقام {میرا} ہے؛ میں اس کا بدلہ دوں گا، خداوند فرماتا ہے۔\n20۔ لہٰذا اگر تمہارے دشمن کو بھوک لگے تو اسے کھلاؤ؛ اگر اسے پیاس لگے تو اسے پانی دو، کیونکہ ایسا کرنے سے تم اس کے سر پر آگ کے کوئلے ڈال دو گے۔\n21۔ برائی پر غالب نہ آؤ، بلکہ نیکی سے برائی پر قابو پائو۔","1۔ ہر روح کو اعلیٰ طاقتوں کے تابع ہونا چاہیے۔ کیونکہ خدا کے سوا کوئی طاقت نہیں: جو طاقتیں ہیں وہ خدا کی طرف سے مقرر کی گئی ہیں۔ {مقرر: یا، حکم شدہ}\n2۔ جو بھی طاقت کی مخالفت کرے گا، وہ خدا کے حکم کی مخالفت کرے گا: اور جو مزاحمت کرے گا وہ خود کو عذاب کا سامنا کرے گا۔\n3۔ کیونکہ حکمران اچھے اعمال کے لیے دہشت نہیں بلکہ برائی کے لیے دہشت ہیں۔ کیا تم طاقت سے نہیں ڈرو گے؟ جو اچھا ہے وہ کرو، اور تمہیں اسی کی تعریف ملے گی:\n4۔ کیونکہ وہ خدا کا خادم ہے جو تمہارے لیے بھلائی کے لیے ہے۔ لیکن اگر تم برا کام کرو تو ڈرو؛ کیونکہ وہ تلوار کو بے مقصد نہیں اٹھاتا: کیونکہ وہ خدا کا خادم ہے، جو برائی کرنے والے پر غصہ نازل کرنے کا انتقام لینے والا ہے۔\n5۔ اسی لیے {تمہیں} کو صرف غصے کے لیے نہیں بلکہ ضمیر کے لیے بھی تابع ہونا چاہیے۔\n6۔ کیونکہ اسی مقصد کے لیے آپ خراج بھی ادا کرتے ہیں: کیونکہ وہ خدا کے خادم ہیں، جو مسلسل اسی کام میں مصروف ہیں۔\n7۔ اس لیے ان کے تمام واجبات کو واجب الادا کریں: وہ خراج جسے خراج {واجب الادا ہے}؛ رواج کس کے ساتھ رواج تھا؛ خوف کس سے خوفزدہ ہے؛ عزت کس کو عزت دی جاتی ہے۔\n8۔ کسی کا مقروض نہ ہو، سوائے ایک دوسرے سے محبت کرنے کے: کیونکہ جو دوسروں سے محبت کرتا ہے اس نے شریعت پوری کی ہے۔\n9۔ اس کے لیے، تم نہیں کرو گے، قتل نہیں کرو گے، چوری نہیں کرو گے، جھوٹی گواہی نہیں دے گا، لالچ نہیں کرو گے؛ اور اگر کوئی اور حکم ہے، تو اسے مختصرا اس کہاوت میں سمجھا گیا ہے، یعنی، تو اپنے پڑوسی سے ویسا ہی محبت کرو جیسے تم خود کرو۔\n10۔ محبت اپنے پڑوسی کے لیے برا نہیں کرتی: اس لیے محبت قانون کی تکمیل ہے۔\n11. اور یہ کہ، وقت کو جانتے ہوئے، اب نیند سے جاگنے کا وقت ہے: کیونکہ اب ہماری نجات اس وقت سے زیادہ قریب ہے جب ہم ایمان رکھتے تھے۔\n12۔ رات بہت دور گزر چکی ہے، دن قریب آ گیا ہے: لہٰذا ہم تاریکی کے کاموں کو چھوڑ دیں، اور روشنی کا زرہ پہنیں۔\n13۔ آئیے دن کی طرح ایمانداری سے چلیں؛ نہ ہنگامہ آرائی اور نشے میں، نہ کمرے میں اور بے حسی میں، نہ جھگڑے اور حسد میں۔ {سچ کہوں تو: یا، مناسب طور پر}\n14۔ لیکن تم خداوند یسوع مسیح پر پہنو، اور جسم کے لیے خوراک نہ بناؤ، تاکہ {ہوس} پوری ہو۔","1۔ جو ایمان میں کمزور ہے وہ تمہیں قبول کرے، {لیکن} مشکوک بحثوں سے بچے۔ {نہیں...: یا، اس کے مشکوک خیالات کا فیصلہ نہ کروں}\n2۔ کیونکہ ایک ایمان رکھتا ہے کہ وہ سب کچھ کھا سکتا ہے؛ دوسرا جو کمزور ہے، جڑی بوٹیاں کھاتا ہے۔\n3۔ جو کھاتا ہے وہ اس سے حقیر نہ ہو جو نہیں کھاتا؛ اور جو کھاتا ہے وہ کھانے والے کا فیصلہ نہ کرے، کیونکہ خدا نے اسے قبول کر لیا ہے۔\n4. تم کون ہو جو کسی اور کے خادم کا فیصلہ کرتا ہے؟ وہ اپنے مالک کے سامنے کھڑا ہوتا ہے یا گرتا ہے۔ ہاں، اسے تھام لیا جائے گا: کیونکہ خدا اسے کھڑا کرنے کے قابل ہے۔\n5۔ ایک آدمی ایک دن کو دوسرے دن سے فوقیت دیتا ہے: دوسرا ہر دن {یکساں طور پر}۔ ہر آدمی اپنے ذہن میں مکمل طور پر قائل ہو۔ {مکمل قائل: یا، مکمل یقین دہانی}\n6۔ جو دن کو دیکھتا ہے، وہ خداوند کو دیکھتا ہے؛ اور جو دن کو نہیں دیکھتا، وہ خدا کی طرف نہیں دیکھتا۔ جو کھاتا ہے، وہ خداوند کے لیے کھاتا ہے، کیونکہ وہ خدا کا شکر ادا کرتا ہے؛ اور جو نہیں کھاتا، وہ خداوند کے لیے نہیں کھاتا اور خدا کا شکر ادا کرتا ہے۔ {غور کریں: یا، مشاہدہ کریں}\n7۔ کیونکہ ہم میں سے کوئی اپنے لیے نہیں جیتا، اور کوئی انسان اپنے لیے نہیں مرتا۔\n8۔ کیونکہ اگر ہم زندہ ہیں، تو ہم خداوند کے لیے جیتے ہیں؛ اور چاہے ہم مر جائیں، ہم خداوند کے لیے مرتے ہیں: چاہے ہم زندہ رہیں یا مریں، ہم خداوند کے ہیں۔\n9۔ اسی مقصد کے لیے مسیح نے مرنا بھی کیا، زندہ ہوا، اور دوبارہ زندہ ہوا، تاکہ وہ مردوں اور زندوں دونوں کا رب بن سکے۔\n10۔ لیکن تم اپنے بھائی کا فیصلہ کیوں کرتے ہو؟ یا تم اپنے بھائی کو کیوں نہیں سمجھتے؟ کیونکہ ہم سب مسیح کی عدالت کی نشست کے سامنے کھڑے ہوں گے۔\n11۔ کیونکہ یہ لکھا ہے، {جت} میں زندہ ہوں، خداوند فرماتا ہے، ہر گھٹنے میرے سامنے جھکے گا، اور ہر زبان خدا کے سامنے اعتراف کرے گی۔\n12۔ تو پھر ہم میں سے ہر ایک خدا کے سامنے اپنا حساب دے گا۔\n13۔ لہٰذا ہم ایک دوسرے کا فیصلہ نہ کریں، بلکہ یہ فیصلہ کریں کہ کوئی شخص اپنے بھائی کے راستے میں رکاوٹ یا رکاوٹ نہ ڈالے۔\n14. میں جانتا ہوں، اور خداوند یسوع کی طرف سے قائل ہوں کہ {خود میں کچھ بھی ناپاک نہیں} ہے: سوائے اس کے جو کسی چیز کو ناپاک سمجھتا ہے، اس کے لیے وہ ناپاک ہے۔ {ناپاک: عام انگریزی}\n15۔ لیکن اگر تمہارا بھائی تمہارے گوشت سے غمگین ہے، تو اب تم خیرات سے نہیں چلتے۔ اپنے گوشت سے اسے تباہ نہ کرو، جس کے لیے مسیح مرا تھا۔ {خیرات کے ساتھ: خیرات کے مطابق}\n16. پھر تمہاری بھلائی کو برائی نہ بننے دو:\n17۔ کیونکہ خدا کی بادشاہی گوشت اور پینا نہیں ہے؛ بلکہ راستبازی، امن، اور روح القدس میں خوشی۔\n18۔ کیونکہ جو ان چیزوں میں مسیح کی خدمت کرتا ہے وہ خدا کے لیے قابل قبول ہے اور انسانوں کی منظوری دیتا ہے۔\n19۔ لہٰذا آئیے ان چیزوں کی پیروی کریں جو امن کا باعث بنتی ہیں، اور وہ چیزیں جن سے ایک دوسرے کو تعلیم دے سکتا ہے۔\n20۔ کیونکہ گوشت خدا کے کام کو تباہ نہ کرے۔ تمام چیزیں واقعی {پاک} ہیں؛ لیکن {یہ} اس شخص کے لیے برا ہے جو برا کھاتا ہے۔\n21. نہ گوشت کھانا اچھا ہے، نہ شراب پینا اور نہ ہی کوئی ایسی چیز جس سے تمہارا بھائی ٹھوکر کھائے، یا ناراض ہو، یا کمزور ہو جائے۔\n22. کیا تم ایمان رکھتے ہو؟ خدا کے سامنے اپنے لیے رکھو۔ مبارک وہ ہے جو خود کو اس چیز میں ملامت نہیں کرتا جسے وہ اجازت دیتا ہے۔\n23. اور جو شک کرتا ہے وہ ملعون ہے اگر وہ کھائے، کیونکہ {وہ ایمان سے نہیں کھاتا}؛ کیونکہ جو {ایمان کا نہیں} وہ گناہ ہے۔ {شک کرتا ہے: یا، گوشت میں فرق پہچانتا ہے اور رکھتا ہے} {لعنتی: یا، سزا یافتہ، یا سزا کے قابل ہو}","1۔ پھر ہم جو مضبوط ہیں کمزوروں کی کمزوریوں کو برداشت کریں، نہ کہ خود کو خوش کریں۔\n2. ہم میں سے ہر ایک اپنے پڑوسی کو اس کی بھلائی کے لیے خوش کرے۔\n3۔ کیونکہ یہاں تک کہ مسیح نے خود کو پسند نہیں کیا؛ لیکن، جیسا کہ لکھا ہے، جن لوگوں نے تمہیں ملامت کی، وہ مجھ پر پڑے۔\n4۔ کیونکہ جو کچھ بھی پہلے لکھا گیا تھا وہ ہمارے علم کے لیے لکھا گیا تھا، تاکہ ہم صبر اور صحیفوں کی تسلی کے ذریعے امید حاصل کر سکیں۔\n5. اب صبر اور تسلی کا خدا آپ دونوں کو مسیح یسوع کے مطابق ایک دوسرے کے ساتھ ہم خیال بننے کی اجازت دیتا ہے: {کے مطابق: یا، مثال کے مطابق}\n6۔ تاکہ آپ ایک ذہن اور ایک منہ سے خدا کی جلال کریں، حتیٰ کہ ہمارے رب یسوع مسیح کے باپ کو بھی۔\n7۔ اسی لیے ایک دوسرے کو قبول کرو، جیسے مسیح نے بھی ہمیں خدا کی جلال کے لیے قبول کیا۔\n8۔ اب میں کہتا ہوں کہ یسوع مسیح خدا کی سچائی کے لیے ختنہ کے خادم تھے، تاکہ وہ باپ سے کیے گئے وعدوں کی تصدیق کر سکیں:\n9۔ اور تاکہ غیر یہودی خدا کی {اس کی} رحمت کے لیے جلال بخشیں؛ جیسا کہ لکھا ہے، اسی مقصد کے لیے میں غیر یہودیوں میں تمہیں اعتراف کروں گا، اور تیرے نام کے لیے گاؤں گا۔\n10۔ اور پھر وہ کہتا ہے، اے غیر یہودیوں، اپنے لوگوں کے ساتھ خوش رہو۔\n11. اور پھر، اے تمام غیر یہودیوں، خداوند کی تعریف کرو؛ اور اس کی تعریف کرو، تم سب لوگ۔\n12۔ اور پھر، یسیاس کہتا ہے، یسوع کی جڑ ہوگی، اور جو غیر قوموں پر حکومت کرے گا؛ غیر یہودیاں اس پر بھروسہ کریں گی۔\n13۔ اب امید کا خدا آپ کو تمام خوشی اور ایمان میں سکون عطا کرتا ہے، تاکہ آپ روح القدس کی طاقت کے ذریعے امید سے بھرپور ہوں۔\n14۔ اور میں خود بھی تم سے قائل ہوں، میرے بھائیو، کہ تم بھی نیکی سے بھرے ہو، تمام علم سے بھرے ہو، اور ایک دوسرے کو نصیحت کرنے کے قابل ہو۔\n15۔ بہرحال، بھائیو، میں نے آپ کو کسی نہ کسی طرح زیادہ جرات مندانہ انداز میں لکھا ہے، تاکہ آپ کو یاد رکھ سکوں، خدا کی طرف سے مجھے دی گئی رحمت کی وجہ سے،\n16. کہ میں یسوع مسیح کا خادم بنوں، خدا کی خوشخبری کی خدمت کروں، تاکہ غیر قوموں کی قربانی قابل قبول ہو، کیونکہ وہ روح القدس کے ذریعے پاک ہو سکتے ہیں۔ {قربانی: یا، قربانی دینا}\n17. اس لیے میں یسوع مسیح کے ذریعے ان چیزوں میں جلال حاصل کر سکتا ہوں جو خدا سے متعلق ہیں۔\n18۔ کیونکہ میں ان چیزوں کے بارے میں بات کرنے کی جرات نہیں کروں گا جو مسیح نے میرے ذریعے نہیں کی، تاکہ غیر قوموں کو الفاظ اور عمل سے فرمانبردار بنایا جا سکے،\n19۔ عظیم نشانات اور عجائبات کے ذریعے، خدا کی روح کی طاقت سے؛ تاکہ یروشلم سے، اور ایلیریکم تک، میں نے مسیح کی خوشخبری مکمل طور پر سنائی ہو۔\n20۔ ہاں، میں نے بھی انجیل کی تبلیغ کرنے کی کوشش کی ہے، نہ کہ جہاں مسیح کا نام رکھا گیا تھا، ورنہ میں کسی اور کی بنیاد پر تعمیر کروں گا:\n21۔ لیکن جیسا کہ لکھا ہے، جس سے اس کا ذکر نہیں ہوا، وہ دیکھیں گے: اور جو نہیں سنا وہ سمجھ جائے گا۔\n22۔ اسی وجہ سے مجھے آپ کے پاس آنے سے بہت روکا گیا ہے۔ {بہت زیادہ: یا، کئی طریقوں سے، یا اکثر اوقات}\n23۔ لیکن اب جب کہ آپ کے پاس ان علاقوں میں کوئی جگہ نہیں رہی، اور اتنے سالوں سے آپ کے پاس آنے کی شدید خواہش ہے؛\n24۔ جب بھی میں اسپین کا سفر کروں گا، میں تمہارے پاس آؤں گا: کیونکہ مجھے امید ہے کہ میں تمہیں اپنے سفر میں دیکھوں گا، اور تم مجھے وہاں لے جاؤں گا، اگر پہلے میں تمہاری صحبت سے کچھ بھر جاؤں۔ {with...: Gr. with you}\n25۔ لیکن اب میں یروشلم جا رہا ہوں تاکہ مقدسین کی خدمت کروں۔\n26۔ کیونکہ مقدونیہ اور اخایا کے لیے یہ خوش ہوا ہے کہ وہ یروشلم میں موجود غریب مقدسین کے لیے کچھ حصہ ڈالیں۔\n27۔ یہ انہیں واقعی پسند آیا؛ اور وہ اپنے مقروض ہیں۔ کیونکہ اگر غیر یہودیوں کو ان کی روحانی چیزوں میں شریک بنایا گیا ہے، تو ان کا فرض بھی ہے کہ وہ جسمانی امور میں ان کی خدمت کریں۔\n28۔ جب میں یہ کر لوں اور ان کے لیے یہ پھل مہر لگا دوں، تو میں تمہارے ساتھ اسپین آؤں گا۔\n29۔ اور مجھے یقین ہے کہ جب میں تمہارے پاس آؤں گا، تو مسیح کی انجیل کی برکت کی مکمل تکمیل کے ساتھ آؤں گا۔\n30. اب میں آپ سب سے درخواست کرتا ہوں، بھائیو، خداوند یسوع مسیح کی خاطر، اور روح کی محبت کے لیے، کہ آپ میرے لیے خدا سے اپنی دعاؤں میں میرے ساتھ مل کر کوشش کریں؛\n31۔ تاکہ میں ان لوگوں سے آزاد ہو جاؤں جو یہودیہ پر ایمان نہیں رکھتے؛ اور تاکہ یروشلم کے لیے میری خدمت مقدسین سے قبول کی جائے؛ {نہیں...: یا، نافرمان ہیں}\n32. تاکہ میں خدا کی مرضی سے خوشی کے ساتھ تمہارے پاس آؤں، اور تمہارے ساتھ تازہ دم ہو جاؤں۔\n33۔ اب امن کا خدا {ہو} تم سب کے ساتھ۔ آمین۔","1۔ میں آپ کو فیبی کی بہن کی تعریف کرتا ہوں، جو سینکریا میں موجود چرچ کی خادمہ ہے:\n2۔ کہ تم اسے خداوند میں قبول کرو، جیسا کہ وہ مقدس بنتی ہے، اور جو بھی کام اسے تم سے چاہیے اس میں مدد کرو، کیونکہ وہ بہت سے لوگوں کی مدد کر چکی ہے، اور میرے لیے بھی۔\n3۔ میرے معاونین پرسیلا اور ایکویلا کو مسیح عیسیٰ میں سلام کرو:\n4۔ جنہوں نے میری جان کے لیے اپنی گردن ڈال دی: جن کا نہ صرف میں شکر گزار ہوں بلکہ غیر یہودیوں کی تمام کلیساؤں کا بھی۔\n5. اسی طرح ان کے گھر میں موجود چرچ کو بھی خوش آمدید کہیں۔ میرے محبوب ایپینیٹس کو سلام کرو، جو مسیح کے لیے آخایا کے پہلے پھل ہیں۔\n6۔ مریم کو سلام کرو، جس نے ہمیں بہت محنت دی۔\n7۔ اینڈرونیکس اور جونیا، میرے رشتہ داروں اور میرے ساتھی قیدیوں کو سلام کرو، جو رسولوں میں نمایاں ہیں اور میرے پہلے مسیح میں تھے۔\n8۔ ایمپلیاس، میرے محبوب کو خداوند میں سلام کرو۔\n9. اربن کو سلام، ہمارے مسیح میں مددگار، اور میرے محبوب اسٹاچس۔\n10. سلام اپیلس کو مسیح میں منظور کیا گیا۔ ان لوگوں کو سلام کرو جو ارسطوبولس کے {گھرانے} سے ہیں۔ {گھران: یا، دوست}\n11۔ ہیروڈین کو سلام کرو، میرے رشتہ دار۔ ان لوگوں کو سلام کرو جو نرکیسس کے گھرانے سے ہیں، جو خداوند میں ہیں۔ {گھران: یا، دوست}\n12۔ ٹریفینا اور ٹرائیفوسا کو سلام کرو، جو خداوند میں محنت کرتے ہیں۔ محبوب پرسس کو سلام کرو، جس نے خداوند میں بہت محنت کی۔\n13۔ خداوند میں منتخب روفس کو سلام، اور اس کی ماں اور میری ماں کو۔\n14۔ سلام اسینکریٹس، فلیگون، ہرماس، پیٹروباس، ہرمیس، اور ان کے ساتھ موجود بھائیوں کو۔\n15۔ فیلولوگس، جولیا، نیریئس، اور اس کی بہن، اور اولمپاس اور ان کے ساتھ موجود تمام مقدسین کو سلام۔\n16۔ ایک دوسرے کو مقدس بوسے سے سلام کرو۔ مسیح کے گرجا گھر آپ کو سلام پیش کرتے ہیں۔\n17۔ اب میں آپ سے التجا کرتا ہوں، بھائیو، ان لوگوں کو نوٹ کریں جو آپ کے سیکھے ہوئے عقیدے کے خلاف تقسیم اور جرائم کا باعث بنتے ہیں؛ اور ان سے دور رہیں۔\n18۔ کیونکہ جو ایسے ہیں وہ ہمارے رب یسوع مسیح کی عبادت نہیں کرتے بلکہ اپنے پیٹ کی خدمت کرتے ہیں؛ اور اچھے الفاظ اور منصفانہ باتوں سے سادہ لوگوں کے دلوں کو دھوکہ دیتے ہیں۔\n19۔ کیونکہ تمہاری اطاعت سب {انسانوں} کے لیے باہر آ رہی ہے۔ اس لیے میں آپ کی طرف سے خوش ہوں: لیکن پھر بھی میں چاہتا ہوں کہ آپ برائی کے بارے میں نیکی اور سادہ چیزوں کے بارے میں دانا ہوں۔ {سادہ: یا، بے ضرر}\n20. اور امن کا خدا جلد ہی شیطان کو تمہارے قدموں تلے زخمی کر دے گا۔ ہمارے رب یسوع مسیح کا فضل آپ کے ساتھ ہو۔ آمین۔ {زخم: یا، ٹریڈ}\n21۔ تیموتھیئس میرے ساتھی، اور لوشیس، اور جیسن، اور سوسیپیٹر، میرے رشتہ دار، تمہیں سلام پیش کرتے ہیں۔\n22۔ میں ترٹیئس، جس نے {یہ} خط لکھا، خداوند میں تمہیں سلام پیش کرتا ہوں۔\n23. گائوس، میرا میرا لشکر، اور پوری کلیسیا میں، آپ کو سلام پیش کرتا ہے۔ ایراسٹس، شہر کا چیمبرلین، تمہیں سلام کرتا ہے، اور کوارٹس بھائی کو۔\n24. ہمارے رب یسوع مسیح کا فضل آپ سب کے ساتھ ہو۔ آمین۔\n25۔ اب اس کے پاس جو تمہیں میری انجیل کے مطابق اور یسوع مسیح کی تبلیغ کے مطابق، اس راز کے انکشاف کے مطابق قائم کرے، جو دنیا کے آغاز سے راز میں رکھا گیا تھا،\n26۔ لیکن اب یہ ظاہر ہو گیا ہے، اور نبیوں کی صحیفوں کے ذریعے، ابدی خدا کے حکم کے مطابق، جو تمام قوموں کو ایمان کی اطاعت کے لیے معلوم کیا گیا ہے:\n27. صرف خدا کے لیے جو دانا ہے، ہمیشہ کے لیے یسوع مسیح کے ذریعے جلال رکھو۔ آمین۔ «{کورنتھس سے رومیوں کو لکھا گیا، اور بھیجا گیا} فیبے نے سینکریا کی چرچ کی خدمت گزار کی طرف سے۔}»"];
